 rows.push(row(r,[cell('B2','СТУДИЯ ПЕЧАТИ · БАРНАУЛ',ST.brandSub),cell('E2','tekkkst@yandex.ru',ST.contact)],18));merges.push('B2:D2','E2:F2');r++;
