 const itemStart=r;
 for(const it of items){const lines=it.name.split('\n').length,h=Math.max(28,14+lines*14);rows.push(row(r,[cell('A'+r,it.n,ST.qty),cell('B'+r,it.code,ST.center),cell('C'+r,it.name,ST.bodyWrap),cell('D'+r,it.q,ST.qty),cell('E'+r,it.price,ST.unitMoney),cell('F'+r,it.sum,ST.money,it.continuation?{}:{formula:`IF(ISNUMBER(E${r}),ROUND(D${r}*E${r},2),"")`,cached:it.sum??''})],h));r++;}
 const itemEnd=r-1;
